#include <omp.h>
#include <cstddef>
#include <string>
#include <vector>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    long long last_index = -1;
    const long long n = static_cast<long long>(books.size());

    #pragma omp parallel for reduction(max:last_index)
    for (long long i = 0; i < n; ++i) {
        if (books[static_cast<std::size_t>(i)].pages < 100 && i > last_index) {
            last_index = i;
        }
    }

    return (last_index >= 0)
        ? static_cast<std::size_t>(last_index)
        : books.size();
}
